import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Fixed-value regression checks, not expectations generated by the extractor. */
public class RegexExtractorChecks {
    private static void check(boolean value, String message) { if (!value) throw new AssertionError(message); }
    private static void equal(String expected, String actual, String message) {
        check(expected.equals(actual), message + ": expected [" + expected + "] but got [" + actual + "]");
    }
    public static void main(String[] args) throws Exception {
        Path run = Path.of(args.length == 0 ? "crawler-output/2026-10-21_09-33-31_1207958737307495699" : args[0]);
        var metadata = new HashMap<String, String>();
        for (String row : Files.readAllLines(run.resolve("pages.tsv"), StandardCharsets.UTF_8).subList(1,
                Files.readAllLines(run.resolve("pages.tsv"), StandardCharsets.UTF_8).size())) {
            String[] fields = row.split("\t", -1);
            metadata.put(Path.of(fields[5]).getFileName().toString(), fields[1]);
        }
        List<String> golden = Files.readAllLines(Path.of("test-fixtures/regex-golden-20.tsv"), StandardCharsets.UTF_8);
        String[] columns = golden.get(0).split("\t");
        Set<String> uniqueUrls = new HashSet<>(); int assertions = 0;
        for (String line : golden.subList(1, golden.size())) {
            String[] expected = line.split("\t", -1);
            String url = metadata.get(expected[0]);
            check(url != null && uniqueUrls.add(url), "Each fixture must identify a distinct existing page: " + expected[0]);
            var result = MusicBrainzRegexExtractor.extract(url,
                Files.readString(run.resolve("html").resolve(expected[0]), StandardCharsets.UTF_8));
            for (int i = 1; i < columns.length; i++) {
                String value = switch (columns[i]) {
                    case "dates" -> String.join(";", result.events().stream().map(MusicBrainzRegexExtractor.Event::date).toList());
                    case "countries" -> String.join(";", result.events().stream().map(MusicBrainzRegexExtractor.Event::country).toList());
                    default -> result.fields().get(columns[i]);
                };
                equal(expected[i], value, expected[0] + " / " + columns[i]); assertions++;
            }
            check(result.warnings().isEmpty(), "Unexpected warnings for " + expected[0] + ": " + result.warnings());
            if (expected[1].equals("artist")) {
                equal("1991", result.fields().get("artist_begin_date"), "Artist begin date must not include relative age");
                equal("United Kingdom", result.fields().get("area"), "Artist area");
                check(result.links().contains(new MusicBrainzRegexExtractor.Link("wikidata_reference",
                    "https://www.wikidata.org/wiki/Q44190")), "Artist Wikidata reference");
            } else {
                equal("a74b1b7f-71a5-4011-9441-d0b5e4122711", result.fields().get("artist_mbids"), "Credited artist MBID");
            }
            if (expected[1].equals("release")) {
                equal("Official", result.fields().get("status"), "Release status");
                equal("English", result.fields().get("language"), "Release language");
                check(result.links().contains(new MusicBrainzRegexExtractor.Link("release_group",
                    "https://musicbrainz.org/release-group/b1392450-e666-3926-a536-22c65f834433")), "Release-group relation");
            }
        }
        check(uniqueUrls.size() >= 20, "Must cover at least 20 distinct real pages");
        syntheticChecks();
        System.out.println("REGEX checks passed: " + uniqueUrls.size() + " real pages, " + assertions
            + " fixed-value field comparisons, plus identity, links and synthetic edge cases.");
    }
    private static void syntheticChecks() throws Exception {
        String id = "00000000-0000-0000-0000-000000000001";
        String url = "https://musicbrainz.org/release/" + id;
        String html = "<html><head><title>Release - MusicBrainz</title></head><body>"
            + "<script><h1>FAKE</h1><dd class='barcode'>WRONG</dd></script><!-- <h1>FAKE</h1> -->"
            + "<h1><a href='/release/" + id + "'><bdi>A &amp; B &#x1F3B5;</bdi></a> (comment)</h1>"
            + "<p class='other subheader'>~ Release by <a href='/artist/" + id + "'>A</a> &amp; "
            + "<a href='/artist/00000000-0000-0000-0000-000000000002'>B</a>"
            + "<span class='small'>(<a href='/release-group/" + id + "'>see all versions</a>)</span></p>"
            + "<dl class='not-properties'><dd class='barcode'>WRONG</dd></dl>"
            + "<dl class='properties'><dd class='format'>2×<span>CD</span></dd></dl>"
            + "<li class='release-event'><span><a href='/area/" + id + "'>France</a></span>"
            + "<span class='release-date'>2001-??-??</span></li></body></html>";
        var result = MusicBrainzRegexExtractor.extract(url, html);
        equal("A & B 🎵", result.fields().get("name"), "Decode numeric/named entities; heading comment is not the name");
        equal("A & B", result.fields().get("artist_credit"), "Preserve collaborative artist credit without version note");
        equal("2×CD", result.fields().get("format"), "Do not invent spaces around inline tags");
        equal("", result.fields().get("barcode"), "Missing barcode stays empty; ignore scripts and wrong CSS class");
        check(result.fields().get("artist_mbids").split(";").length == 2, "Preserve both credited artists");
        check(result.events().equals(List.of(new MusicBrainzRegexExtractor.Event("France", "2001-??-??"))),
            "Preserve partial date and associated country");
        for (String bad : List.of("<html><title>Verifying your browser</title></html>",
                html.replace("</html>", ""), html.replace("href='/release/" + id, "href='/release/ffffffff-ffff-ffff-ffff-ffffffffffff"))) {
            try { MusicBrainzRegexExtractor.extract(url, bad); throw new AssertionError("Invalid page accepted"); }
            catch (java.io.IOException expected) { }
        }
    }
}
